def solve(s):
    """Convert a Roman numeral to integer, handling whitespace and case.
    Returns 0 for any invalid characters.
    """
    if not isinstance(s, str):
        return 0
    s = s.strip().upper()
    roman = {'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}
    total = 0
    i = 0
    n = len(s)
    while i < n:
        # get value of current symbol, if invalid treat as 0 and break
        if s[i] not in roman:
            return 0
        if i+1 < n and s[i+1] not in roman:
            return 0
        if i+1 < n and roman[s[i]] < roman[s[i+1]]:
            total += roman[s[i+1]] - roman[s[i]]
            i += 2
        else:
            total += roman[s[i]]
            i += 1
    return total

