def solve(s):
    """Run-length encoding for any iterable of hashable elements.
    If s is not iterable, return an empty list.
    """
    try:
        it = iter(s)
    except TypeError:
        return []
    try:
        prev = next(it)
    except StopIteration:
        return []
    count = 1
    res = []
    for elem in it:
        if elem == prev:
            count += 1
        else:
            res.append([prev, count])
            prev = elem
            count = 1
    res.append([prev, count])
    return res

