    rows = len(grid)
    # visited mirrors grid dimensions for each row
    visited = [ [False]*len(grid[i]) for i in range(rows) ]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if i < 0 or i >= rows:
                continue
            if j < 0 or j >= len(grid[i]):
                continue
            if visited[i][j] or grid[i][j] == 0:
                continue
            visited[i][j] = True
            # neighbours
            stack.append((i-1, j))
            stack.append((i+1, j))
            stack.append((i, j-1))
            stack.append((i, j+1))
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if not visited[i][j] and grid[i][j] == 1:
                dfs(i, j)
                count += 1
    return count

