def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Handles any iterable of comparable items, returns 0 for invalid inputs.
    Implements patience sorting in O(n log n)."""
    import bisect
    # Validate input
    if not isinstance(nums, (list, tuple)):
        return 0
    if not nums:
        return 0
    tails = []  # tails[i] = smallest possible tail of an inc subseq of length i+1
    for x in nums:
        # Assume elements are comparable; skip if not
        try:
            _ = x < x  # test comparability
        except Exception:
            continue
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

